// Получаем входящее сообщение
let input = msg.payload; 
let resultArray = [];

// Проверяем, что пришло число (используем if/else)
if (typeof input === 'number') {

    // Используем цикл for для создания массива
    for (let i = 1; i <= input; i++) {
        resultArray.push(i * 10); // умножаем каждое число на 10
    }

    // Создаем объект с результатом
    let resultObject = {
        originalNumber: input,
        message: "Успешно обработано",
        processedArray: resultArray
    };

    // Возвращаем объект в msg.payload
    msg.payload = resultObject;

} else {
    // Если пришла не цифра, возвращаем ошибку
    msg.payload = "Ошибка: ожидалось число!";
}

// Обязательно возвращаем msg в конце
return msg;
